def parse_time(string: str) ->Optional[mod_datetime.datetime]:
    match = RE_TIMESTAMP.match(string)
    if not match:
        return None

    year, month, day, hour, minute, second, frac, tz = match.groups()

    year = int(year)
    month = int(month)
    day = int(day)
    hour = int(hour)
    minute = int(minute)
    second = int(second)

    microsecond = 0
    if frac:
        frac = frac[1:]
        if len(frac) <= 6:
            microsecond = int(frac.ljust(6, '0'))
        else:
            microsecond = int(frac[:6])

    tzinfo = None
    if tz:
        if tz == 'Z':
            tzinfo = SimpleTZ()
        else:
            tzinfo = SimpleTZ(tz)

    return mod_datetime.datetime(year, month, day, hour, minute, second, microsecond, tzinfo=tzinfo)

def gpx_fields_from_xml(class_or_instance: Any, node: str, version: str) ->Any:
    if mod_inspect.isclass(class_or_instance):
        instance = class_or_instance()
    else:
        instance = class_or_instance

    fields = instance.gpx_10_fields
    if version == '1.1':
        fields = instance.gpx_11_fields

    for field in fields:
        if isinstance(field, str):
            continue

        value = field.from_xml(node, version)
        setattr(instance, field.name, value)

    return instance

def from_string(self, string: str) ->Optional[mod_datetime.datetime]:
    return parse_time(string)

def from_xml(self, node: Any, version: str) ->Any:
    if node is not None:
        result = node.text
    else:
        result = None

    if result is None:
        return None

    return parse_time(result)
